/**
 * People, and what they remember.
 *
 * The single mechanic that separates this from a spreadsheet: an NPC's
 * disposition toward the player is not a slider the model sets, it is a
 * growing list of things that actually happened, plus a derived number. The
 * model reads both; it writes neither.
 *
 * Why memories rather than just a number:
 *
 *   · A number alone lets the model narrate any relationship it likes and then
 *     quietly assert the number matches.
 *   · Memories are quotable. "曹操记得你在酸枣替他挡过一次追兵" is a sentence the
 *     model can use; "+5" is not.
 *   · Memories are the audit trail for a betrayal. If you abandon someone who
 *     trusted you, that fact is written down, and it follows you.
 *
 * Disposition is bounded [-100, 100] and derived on read from memories so the
 * two can never disagree.
 */

import { rollDie } from './rng.js'

/** Moods are coarse on purpose; fine-grained moods are not observable anyway. */
export const MOODS = ['calm', 'wary', 'warm', 'cold', 'hostile', 'calculating']

/** Default disposition contribution by memory kind. */
export const MEMORY_WEIGHT = {
  kindness: 12,
  aid: 8,
  betrayal: -25,
  insult: -10,
  defeat: -6,
  gift: 6,
  oath: 20,
  abandonment: -30
}

/** Cap on how many memories we keep per person; oldest are dropped. */
export const MEMORY_LIMIT = 12

