/** Create the runtime record for a person the first time they matter. */
export function instantiate(personId, seedDisposition = 0) {
  const template = PEOPLE[personId]
  if (template === undefined) {
    return null
  }
  return {
    id: personId,
    name: template.name,
    courtesy: template.courtesy,
    attrs: { ...template.attrs },
    traits: [...template.traits],
    note: template.note,
    mood: 'calm',
    memories: [],
    met: false,
    dispositionSeed: seedDisposition
  }
}

/**
 * Derive disposition from memories. Bounded, and seeded so an NPC with no
 * history still has an initial stance (张飞 starts warm, 督邮 starts cold).
 */
export function dispositionOf(person) {
  if (person === null || person === undefined) return 0
  let total = Number.isFinite(person.dispositionSeed) ? person.dispositionSeed : 0
  for (const memory of person.memories ?? []) {
    const weight = MEMORY_WEIGHT[memory.kind] ?? 0
    total += weight * (Number.isFinite(memory.weight) ? memory.weight : 1)
  }
  return Math.max(-100, Math.min(100, Math.round(total)))
}

/** Human-readable stance label. The model may quote this; it may not re-derive it. */
export function stanceLabel(disposition) {
  if (disposition >= 60) return '死心塌地'
  if (disposition >= 30) return '倾心相待'
  if (disposition >= 10) return '颇有好感'
  if (disposition > -10) return '平淡'
  if (disposition > -30) return '心存芥蒂'
  if (disposition > -60) return '深恶之'
  return '誓不两立'
}

/**
 * Record one memory. Returns a NEW person record.
 *
 * `text` is what the player would say about it — it is quoted verbatim in
 * digests, so it must be a fact ("你在酸枣替他挡了一次追兵"), never an
 * interpretation ("他其实很感激你").
 */
export function remember(person, memory) {
  if (person === null || person === undefined) return person
  const record = {
    kind: memory.kind ?? 'kindness',
    text: String(memory.text ?? ''),
    turn: Number.isFinite(memory.turn) ? memory.turn : 0,
    weight: Number.isFinite(memory.weight) ? memory.weight : 1
  }
  const memories = [...(person.memories ?? []), record]
  // Keep the most recent MEMORY_LIMIT. Dropping the oldest is correct: people
  // remember recent things better, and an unbounded list would bloat the save
  // and the digest.
  const trimmed = memories.slice(Math.max(0, memories.length - MEMORY_LIMIT))
  return { ...person, memories: trimmed, met: true }
}

/**
 * Get-or-create a person record on the save.
 *
 * Creating a record MEANS the player has encountered them: `met` defaults to
 * true. (An unmet person is simply absent from the save; there is no reason to
 * carry the whole cast around, and a record that exists but is flagged unseen
 * would be a second source of truth about who is in play.)
 */
export function ensurePerson(state, personId, seedDisposition = 0, met = true) {
  const people = state.people ?? {}
  if (people[personId] !== undefined) {
    return { state, person: people[personId] }
  }
  const created = instantiate(personId, seedDisposition)
  if (created === null) {
    return { state, person: null }
  }
  const record = { ...created, met }
  return { state: { ...state, people: { ...people, [personId]: record } }, person: record }
}

/** Write a person record back onto the save. */
export function putPerson(state, person) {
  if (person === null || person === undefined) return state
  return { ...state, people: { ...(state.people ?? {}), [person.id]: person } }
}

/**
 * Seasonally nudge moods.
 *
 * Mood is presentation, not mechanics: it changes how the model is allowed to
 * voice someone, while disposition is what actually moves numbers. Keeping them
 * separate prevents "he seemed angry" from silently becoming "-10".
 */
export function driftMoods(state) {
  let rng = state.rng
  const people = { ...(state.people ?? {}) }
  for (const id of Object.keys(people)) {
    const person = people[id]
    const rolled = rollDie(rng, 6)
    rng = rolled.state
    // A 1 in 6 chance of a mood shift; otherwise the mood persists, which
    // reads as a stable personality rather than a mood ring.
    if (rolled.value !== 1) continue
    const disposition = dispositionOf(person)
    const pool = disposition >= 20 ? ['warm', 'calm'] : disposition <= -20 ? ['cold', 'wary'] : MOODS
    const index = rolled.value % pool.length
    people[id] = { ...person, mood: pool[index] }
  }
  return { ...state, people, rng }
}
